function solveProblem(s) {
    let lowerCount = 0;
    let higherCount = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === s[i].toLowerCase() && s[i] !== s[i].toUpperCase()) {
            lowerCount++;
